// src/components/ProductList.tsx
'use client';

import { useState, useMemo, useCallback } from 'react';
import { ProductCard } from './ProductCard';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  inStock: boolean;
}

interface Review {
  id: string;
  productId: string;
  text: string;
  rating: number;
  author: string;
}

interface Props {
  products: Product[];
  reviews: Review[];
}

export function ProductList({ products, reviews }: Props) {
  const [cart, setCart] = useState<string[]>([]);
  const [filter, setFilter] = useState('');
  const [sortBy, setSortBy] = useState<'price' | 'rating'>('price');

  // Pre-compute review counts to avoid recalculating on every render
  const reviewCounts = useMemo(() => {
    return reviews.reduce((acc, review) => {
      acc[review.productId] = (acc[review.productId] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);
  }, [reviews]);

  // Memoize filtered and sorted products to avoid recalculation on every render
  const filteredProducts = useMemo(() => {
    return products
      .filter(p => p.name.toLowerCase().includes(filter.toLowerCase()))
      .filter(p => p.inStock)
      .sort((a, b) => sortBy === 'price' ? a.price - b.price : b.rating - a.rating);
  }, [products, filter, sortBy]);

  const handleAddToCart = useCallback((productId: string) => {
    setCart(prev => [...prev, productId]);
  }, []);

  const getReviewCount = useCallback((productId: string) => {
    return reviewCounts[productId] || 0;
  }, [reviewCounts]);

