function AdvancedAnalysis({ products }: { products: Product[] }) {
  // Using native JavaScript for statistical calculations (much faster, no bundle bloat)

  // Memoize calculations to avoid recalculation on every render
  const stats = useMemo(() => {
    const prices = products.map(p => p.price);
    const ratings = products.map(p => p.rating);
    const reviews = products.map(p => p.reviews);

    // Helper functions for statistics
    const mean = (arr: number[]) => arr.reduce((a, b) => a + b, 0) / arr.length;
    const median = (arr: number[]) => {
      const sorted = [...arr].sort((a, b) => a - b);
      const mid = Math.floor(sorted.length / 2);
      return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
    };
    const std = (arr: number[]) => {
      const m = mean(arr);
      return Math.sqrt(arr.reduce((sum, val) => sum + Math.pow(val - m, 2), 0) / arr.length);
    };
    const variance = (arr: number[]) => {
      const m = mean(arr);
      return arr.reduce((sum, val) => sum + Math.pow(val - m, 2), 0) / arr.length;
    };
    const quantile = (arr: number[], q: number) => {
      const sorted = [...arr].sort((a, b) => a - b);
      const pos = (sorted.length - 1) * q;
      const base = Math.floor(pos);
      const rest = pos - base;
      return sorted[base + 1] !== undefined ? sorted[base] + rest * (sorted[base + 1] - sorted[base]) : sorted[base];
    };

    const priceStats = {
      mean: mean(prices),
      median: median(prices),
      std: std(prices),
      variance: variance(prices),
      q1: quantile(prices, 0.25),
      q3: quantile(prices, 0.75),
    };

    const ratingStats = {
      mean: mean(ratings),
      median: median(ratings),
      std: std(ratings),
    };

    const reviewStats = {
      mean: mean(reviews),
      median: median(reviews),
      std: std(reviews),
    };

    // Calculate value score: rating / price * 100
    const valueScores = products.map(p => ({
      name: p.name,
      score: (p.rating / p.price) * 100,
    }));
    const sortedByValue = [...valueScores].sort((a, b) => b.score - a.score);

    return { priceStats, ratingStats, reviewStats, sortedByValue };
  }, [products]);

  const { priceStats, ratingStats, reviewStats, sortedByValue } = stats;

