];

const ComparisonTable = memo(({ products }: { products: Product[] }) => {
  // Using native JavaScript for data transformations (much faster, no bundle bloat)
  // Memoize calculations to avoid recalculation on every render
  const tableData = useMemo(() => {
    const sorted = [...products].sort((a, b) => a.price - b.price);
    const avgPrice = products.reduce((sum, p) => sum + p.price, 0) / products.length;
    const totalReviews = products.reduce((sum, p) => sum + p.reviews, 0);
    const bestRated = products.reduce((best, p) => p.rating > best.rating ? p : best, products[0]);
    const cheapest = products.reduce((min, p) => p.price < min.price ? p : min, products[0]);
    return { sorted, avgPrice, totalReviews, bestRated, cheapest };
  }, [products]);

  const { sorted, avgPrice, totalReviews, bestRated, cheapest } = tableData;

  return (
